/* The PS1's sound requests as the arcade's effect codes (music.md section 12b), and the sound chunks of the archives built without the disc.
 *
 * Requests. A request is a bank slot (0 to 3) and a start, the entry of the slot's command list where the sound begins. The bank in a slot
 * is known by the id that its VAB header carries (below), so a request finds its cell by (bank id, start). The table is generated by
 * sounds.py --c-table: numbers only.
 *
 * Chunks. The sound parts of an archive (VAB headers, command lists, sequence files and sample bodies, tables 3 to 5) are not read from
 * the disc: every sound is the arcade's effect or nothing, so the game's sound library only needs data it can open and a stream it can
 * finish. arcade_sound_plan reads an archive's header sector (the chunk table: type, size, the first word of each chunk, a sequence
 * group's count) and says which chunks to build; the arcade_sound_* functions write them:
 *   - VAB header: the magic, version 7, the program count the chunk's size gives, one sample whose size is the body chunk's, the bank id
 *     in the id field (offset 8), and one program record for each program. The library reads the magic, the version, the program and
 *     sample counts, the table of sample sizes at the end and one byte of each program record (sdk/libsnd/vs_vh.c);
 *   - command list and sample body: zeros;
 *   - sequence file (SEP): one minimal sequence for each of the group's count (resolution 48, tempo 500000, rhythm 4/4, a body of one
 *     delta and the end of track): what _SsInitSoundSep (sdk/libsnd/sepinit.c) opens;
 * and every chunk begins with the first word of the archive's header record, which the disc stream compares with its first word. */
#ifndef ARCADE_SOUNDS_H
#define ARCADE_SOUNDS_H

#include <stddef.h>
#include <stdint.h>

/* A request that plays nothing on purpose, as code0 and code1 of a row (sounds.py: a stop, which the arcade's player has no PS1 channel
 * for; a sound the PS1 added to a screen or a moment where the arcade has no sound). The runtime plays nothing and counts it as handled. */
#define ARCADE_SOUND_SILENT 0xfffeu

/* A row with this code0 falls back to the PS1's own sound. No row of the table has it now. */
#define ARCADE_SOUND_NONE 0xffffu

/* One sound of one bank. Sorted by (bank, start), for a binary search. */
struct arcade_sound {
    uint16_t bank;               /* the bank's id: its place in arcade_sound_banks plus one */
    uint16_t start;              /* the entry of the bank's command list where the sound begins */
    uint16_t code0, code1;       /* the arcade effect for side 0 and side 1; ARCADE_SOUND_NONE: the PS1's own sound plays; ARCADE_SOUND_SILENT: nothing plays */
    uint8_t method, flags;       /* how the mapping was found (sounds.py); bit 0 of flags: a weak sample match */
};

/* The VAB header chunks of the disc: the file (lower case, as the loader lists it) and the bank slot. Sorted by name then slot. */
struct arcade_sound_bank {
    const char *file;
    uint8_t slot;
};

/* The arcade's pan of an object dx pixels (0 .. 0x17f) right of the camera: pan_first plus the number of edges at or below dx,
 * minus one (16 is the centre of 0 .. 32). */
extern const unsigned arcade_sound_pan_first;
extern const unsigned short arcade_sound_pan_edges[15];
extern const struct arcade_sound_bank arcade_sound_banks[];
extern const unsigned arcade_sound_bank_count;
extern const struct arcade_sound arcade_sounds[];
extern const unsigned arcade_sound_count;

/* The id of the bank of `file` (lower case) in slot `slot`; 0 when the disc has no such header. */
unsigned arcade_sound_bank_id(const char *file, unsigned slot);

/* The cell of (bank id, start), or NULL. */
const struct arcade_sound *arcade_sound_find(unsigned bank, unsigned start);

/* Which chunk. */
enum { ARCADE_SOUND_ZEROS, ARCADE_SOUND_VAB, ARCADE_SOUND_SEP };

#define ARCADE_SOUND_VAB_MAGIC 0x56414270u   /* the first word of a VAB header chunk */
#define ARCADE_SOUND_SEP_MAGIC 0x53455170u   /* the first word of a sequence file */
#define ARCADE_SOUND_CHUNKS 64u              /* chunks an archive header sector holds at most */

struct arcade_sound_chunk {
    unsigned at, size;           /* offset and size in the file */
    unsigned kind;               /* ARCADE_SOUND_ZEROS, _VAB or _SEP */
    unsigned param;              /* the chunk's first word */
    unsigned body;               /* VAB: the bytes of the samples the stream will send (the bank's body chunk) */
    unsigned bank;               /* VAB: the bank's id */
    unsigned count;              /* SEP: the number of sequences */
};

/* The chunks of the archive `file` (lower case) to build, from its header sector `head` (`head_size` bytes, the file has `file_size`):
 * tables 3 (VAB header or command list), 4 (sample body) and 5 (sequence file) that this code can write. A chunk it cannot write (a
 * size that does not fit, a first word that is not the magic) is left out and counted in *skipped. Returns the number of chunks, at most
 * `max`. */
unsigned arcade_sound_plan(const unsigned char *head, unsigned head_size, unsigned file_size, const char *file,
                           struct arcade_sound_chunk *out, unsigned max, unsigned *skipped);

/* Write the chunk into out[0..c->size). */
void arcade_sound_write(const struct arcade_sound_chunk *c, unsigned char *out);

#endif
